def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    opp_budgets = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive.append(opp)
            opp_budgets.append(opp.get('budget', 0))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids_sorted = sorted(prev_bids, reverse=True)
    highest_prev = prev_bids_sorted[int(0)] if len(prev_bids_sorted) >= 1 else DAILY_SALARY * 0.7
    second_prev = prev_bids_sorted[int(1)] if len(prev_bids_sorted) >= 2 else highest_prev * 0.9

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if supply <= 16:
        urgency += 2
    elif supply <= 19:
        urgency += 1

    if day >= 8:
        urgency += 1

    rich_opponents = 0
    for b in opp_budgets:
        if b >= budget:
            rich_opponents += 1
    if rich_opponents >= 2:
        urgency += 1

    if urgency >= 6:
        target = max(highest_prev + 2.0, DAILY_SALARY * 1.4)
    elif urgency >= 4:
        target = max(second_prev + 2.0, DAILY_SALARY * 1.05)
    elif urgency >= 2:
        target = max(DAILY_SALARY * 0.72, second_prev * 0.92)
    else:
        if highest_prev >= DAILY_SALARY * 1.3:
            target = DAILY_SALARY * 0.32
        elif highest_prev >= DAILY_SALARY * 1.0:
            target = DAILY_SALARY * 0.45
        else:
            target = DAILY_SALARY * 0.58

    if budget < DAILY_SALARY * 0.8 and urgency < 4:
        target = min(target, DAILY_SALARY * 0.5)

    if hp <= 2 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.95)

    return float(max(0.0, min(budget, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive_opponents = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace
    yesterday_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Determine target bid based on my hp and yesterday pressure
    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))

    # Supply pressure heuristic: with higher supply, bidding can be lower.
    # Normalize supply into [0,1]
    if MAX_SUPPLY - MIN_SUPPLY > 0:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    supply_norm = max(0.0, min(1.0, float(supply_norm)))

    # Base aggressiveness
    if my_hp <= 2.0:
        base = DAILY_SALARY * 0.95
    elif my_hp <= 4.0:
        base = DAILY_SALARY * 0.70
    else:
        base = DAILY_SALARY * (0.45 + 0.15 * supply_norm)

    # React to yesterday's highest bid: if others were willing to pay near salary, increase to avoid losing.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # If I am not in immediate danger, still raise enough to compete.
        if my_hp > 3.0:
            bid = max(base, DAILY_SALARY * 0.65)
        else:
            bid = max(base, DAILY_SALARY * 0.95)
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        bid = max(base, highest_prev_bid * 0.85)
    else:
        # If yesterday bids were low, don't overpay.
        bid = min(base, max(DAILY_SALARY * 0.55, highest_prev_bid + 5.0))

    # If budget is low, cap aggressively to avoid going broke.
    # Also consider no_water_days: if already accumulating, bid more.
    no_water_days = float(my_status.get('no_water_days', 0))
    if no_water_days >= 2.0:
        bid = max(bid, DAILY_SALARY * 0.75)

    # Final cap
    bid = min(bid, my_budget)

    # If extremely low budget, bid whatever remains (game will likely end anyway)
    if bid <= 0:
        return 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    base_bid = 0.0
    if my_status['hp'] <= 1:
        base_bid = DAILY_SALARY * 0.98
    elif my_status['hp'] <= 3:
        base_bid = DAILY_SALARY * 0.9
    elif my_status['hp'] <= 5:
        base_bid = DAILY_SALARY * 0.75
    else:
        base_bid = DAILY_SALARY * 0.5

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if my_status['hp'] <= 3:
            base_bid = max(base_bid, highest_prev_bid + 5)
        elif my_status['hp'] <= 5:
            base_bid = max(base_bid, highest_prev_bid + 2)
        else:
            if highest_prev_bid >= DAILY_SALARY * 0.9:
                base_bid = max(base_bid, DAILY_SALARY * 0.6)
            else:
                base_bid = max(base_bid, highest_prev_bid + 1)

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2:
        if my_status['hp'] <= 5:
            base_bid = max(base_bid, DAILY_SALARY * 0.95)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.8)
    elif remaining_days <= 4 and my_status['hp'] <= 3:
        base_bid = max(base_bid, DAILY_SALARY * 0.92)

    final_bid = min(my_status['budget'], base_bid)
    final_bid = max(0.0, final_bid)

    return float(final_bid)
